const $=document.querySelector.bind(document),TRANSLATE={"":"无",att:"攻",def:"守",sto:"偷",stopped:"被时停"};function sleep(ms){return new Promise(resolve=>setTimeout(resolve,ms))}function randPick(obj){let sum=0;for(let key of Object.keys(obj))sum+=obj[key];let rand=Math.random()*sum;for(let key of Object.keys(obj))if(rand-=obj[key],rand<=0)return key}function dialog(title,content,confirmText="确定",declinedText="取消"){return new Promise(resolve=>{Swal.fire({title:title,text:content,showDenyButton:!0,confirmButtonText:confirmText,denyButtonText:declinedText}).then(result=>{result.isConfirmed&&resolve(!0),resolve(!1)})})}function arrayShuffle(arr){let newArr=[...arr];for(let i=newArr.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[newArr[i],newArr[j]]=[newArr[j],newArr[i]]}return newArr}